
const STATUS_CODE_ERROR = 2;

export class Span {
	traceId;
	spanId;
	
	parentSpanId;
	name;
	kind;
	startTimeUnixNano;
	endTimeUnixNano;
	traceState = "";
	droppedAttributesCount = 0;
	events;
	droppedEventsCount = 0;
	links = [];
	droppedLinksCount = 0;
	attributes;
	status;
	constructor(traceId, parentSpanId, info, startTimeUnixNano, error) {
		this.traceId = traceId;
		this.spanId = Span.randomSpanId();
		this.parentSpanId = parentSpanId;
		this.name = info.name;
		this.kind = info.kind;
		this.attributes = info.attributes;
		this.startTimeUnixNano = startTimeUnixNano;
		this.endTimeUnixNano = Span.nowUnixNano();
		if (error === undefined) {
			this.status = {
				code: 0,
				message: ""
			};
			this.events = [];
		} else {
			const err = error;
			const message = typeof err?.message === "string" ? err.message : String(error);
			this.status = {
				code: STATUS_CODE_ERROR,
				message
			};
			
			
			const attributes = [];
			if (typeof err?.name === "string") {
				attributes.push({
					key: "exception.type",
					value: { stringValue: err.name }
				});
			}
			attributes.push({
				key: "exception.message",
				value: { stringValue: message }
			});
			if (typeof err?.stack === "string") {
				attributes.push({
					key: "exception.stacktrace",
					value: { stringValue: err.stack }
				});
			}
			this.events = [{
				timeUnixNano: this.endTimeUnixNano,
				name: "exception",
				attributes,
				droppedAttributesCount: 0
			}];
		}
	}
	
	static nowUnixNano() {
		const ms = performance.timeOrigin + performance.now();
		return (BigInt(Math.trunc(ms)) * 1000000n + BigInt(Math.round(ms % 1 * 1e6))).toString();
	}
	
	static randomSpanId() {
		let id = "";
		for (let i = 0; i < 8; i++) {
			id += Math.floor(Math.random() * 256).toString(16).padStart(2, "0");
		}
		return id === "0000000000000000" ? "0000000000000001" : id;
	}
}
